"""
harmonic_reflector.py

Extended with TruthGatedMemory:
Only SHA states that stabilize at the harmonic constant (~0.35) are allowed into memory.
All non-convergent data is rejected as entropic noise.
"""

import hashlib
import numpy as np

HARMONIC_TARGET = 0.35
HARMONIC_TOLERANCE = 0.01
MAX_ITER = 100

class TruthGatedMemory:
    def __init__(self):
        self.memory = []

    def commit(self, data: str):
        result = stabilize_sha(data)
        if not result:
            return False  # Unstable, not accepted

        final_state = result[-1]
        harmonic = final_state[1]

        if abs(harmonic - HARMONIC_TARGET) <= HARMONIC_TOLERANCE:
            self.memory.append({
                'data': data,
                'sha': final_state[0],
                'harmonic': harmonic,
                'delta': final_state[2],
                'history': result
            })
            return True
        return False

    def read_all(self):
        return self.memory

def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def ascii_hexify(hex_str: str) -> str:
    return ''.join(format(ord(c), '02x') for c in hex_str)

def reverse_nibbles(hex_str: str) -> str:
    return hex_str[::-1]

def hex_to_decimal(hex_str: str) -> int:
    return int(hex_str, 16)

def delta_score(h1: str, h2: str) -> int:
    d1 = hex_to_decimal(h1)
    d2 = hex_to_decimal(h2)
    return d1 - d2

def count_trailing_zeros(num: int, base=16) -> int:
    s = format(abs(num), 'x')
    reversed_s = s[::-1]
    return len(reversed_s) - len(reversed_s.lstrip('0'))

def compute_harmonic_ratio(delta: int) -> float:
    total_bits = len(format(abs(delta), 'b'))
    zero_bits = count_trailing_zeros(delta, base=2)
    return zero_bits / total_bits if total_bits > 0 else 0

def stabilize_sha(data: str, max_iter=MAX_ITER):
    current_data = data.encode('utf-8')
    history = []

    for _ in range(max_iter):
        h1 = sha256_hex(current_data)
        ascii_hex = ascii_hexify(h1)
        reversed_ascii_hex = reverse_nibbles(ascii_hex)
        delta = delta_score(ascii_hex, reversed_ascii_hex)
        harmonic = compute_harmonic_ratio(delta)
        history.append((h1, harmonic, delta))

        if abs(harmonic - HARMONIC_TARGET) < HARMONIC_TOLERANCE:
            return history
        current_data = sha256_hex(current_data).encode('utf-8')

    return []

